/* eslint-disable no-unused-vars */
import axios from '@/utils/axiosConfig';
import Checkbox from 'primevue/checkbox';
import Button from 'primevue/button';
import MultiSelect from 'primevue/multiselect';
import AutoComplete from 'primevue/autocomplete';
import { isValidTimeRange } from '@/utils/validation';
import { isActive } from '@/utils/statusHelper';
export default {
  name: 'DailyWorkForm',
  components: {
    Checkbox,
    Button,
    MultiSelect,
    AutoComplete
  },
  inject: ['$toast'],
  created() {
    this.$http = axios;
  },
  data() {
    return {
      tasks: [],
      workflowStepsMap: {},
      taskEntries: [{
        taskId: null,
        stepIds: [],
        location: 'GenT Office',
        workDescription: '',
        files: [],
        eventTitle: '',
        eventDetails: '',
        createCalendarEvent: false,
        createTeamsMeeting: false,
        meetingStartTime: null,
        meetingEndTime: null,
        meetingStartTimeText: '',
        meetingEndTimeText: '',
        meetingStartTimeError: false,
        meetingEndTimeError: false,
        startTimeText: '',
        endTimeText: '',
        startTime: null,
        endTime: null,
        attendees: [],
        selectedAttendee: null,
        filteredAttendees: []
      }],
      minDate: (() => {
        const d = new Date();
        d.setDate(d.getDate() - 1);
        return d;
      })(),
      formData: {
        workDate: new Date(),
        useDateRange: false,
        startDate: new Date(),
        endDate: new Date()
      },
      statusOptions: [],
      users: [],
      isSubmitting: false
    };
  },
  computed: {
    dateRangeDays() {
      if (!this.formData.useDateRange || !this.formData.startDate || !this.formData.endDate) return 0;
      const start = new Date(this.formData.startDate);
      const end = new Date(this.formData.endDate);
      start.setHours(0, 0, 0, 0);
      end.setHours(0, 0, 0, 0);
      const diffTime = end - start;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
      return diffDays > 0 ? diffDays : 0;
    },
    formatDateRange() {
      if (!this.formData.startDate || !this.formData.endDate) return '';
      const start = new Date(this.formData.startDate).toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: 'numeric'
      });
      const end = new Date(this.formData.endDate).toLocaleDateString('th-TH', {
        day: 'numeric',
        month: 'short',
        year: 'numeric'
      });
      return `${start} - ${end}`;
    }
  },
  async mounted() {
    await this.loadTasks();
    await this.loadUsers();
    this.loadStatusOptions();
    // ตั้งค่าเริ่มต้นเวลาปัจจุบัน
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');
    if (this.taskEntries[0]) {
      this.taskEntries[0].startTimeText = timeStr;
      this.taskEntries[0].startTime = new Date(now);
    }
  },
  methods: {
    async loadTasks() {
      try {
        const userId = localStorage.getItem('soc_user_id');
        const [tasksRes, stepsRes] = await Promise.all([axios.get('/api/tasks'), axios.get('/api/task-steps/all')]);
        const availableTasks = tasksRes.data.filter(task => isActive(task.status));
        const assignedTaskIds = new Set(stepsRes.data.filter(s => {
          const users = typeof s.assigned_users === 'string' ? JSON.parse(s.assigned_users) : s.assigned_users;
          return users?.some(u => String(u.id || u) === String(userId));
        }).map(s => s.task_id));
        this.tasks = availableTasks.map(task => ({
          ...task,
          _assigned: assignedTaskIds.has(task.id),
          display: `${task.task_name} ${task.so_number ? `(${task.so_number})` : ''}`
        })).sort((a, b) => (b._assigned ? 1 : 0) - (a._assigned ? 1 : 0));
      } catch (e) {
        console.error(e);
      }
    },
    async onTaskEntryChange(entry) {
      entry.stepIds = [];
      entry.eventDetails = '';
      // Auto-fill eventTitle from SO + task name
      const task = this.tasks.find(t => t.id === entry.taskId);
      if (task) {
        entry.eventTitle = task.so_number ? `[${task.so_number}] ${task.task_name}` : task.task_name;
      }
      if (entry.taskId && !this.workflowStepsMap[entry.taskId]) {
        try {
          const res = await axios.get(`/api/task-steps/task/${entry.taskId}`);
          this.workflowStepsMap[entry.taskId] = res.data || [];
        } catch (e) {
          console.error(e);
        }
      }
    },
    onStepIdsChange(entry) {
      if (!entry.stepIds || entry.stepIds.length === 0) {
        entry.eventDetails = '';
        return;
      }
      const steps = entry.stepIds.map(id => {
        const step = this.getStepByIdFromTask(id, entry.taskId);
        const num = this.getStepNumberFromTask(id, entry.taskId);
        return step ? {
          ...step,
          _num: num
        } : null;
      }).filter(Boolean).sort((a, b) => a._num - b._num);
      entry.eventDetails = steps.map(s => {
        const lines = [`${s._num}. ${s.step_name}`];
        if (s.description) lines.push(`   📋 ${s.description}`);
        if (s.start_date || s.end_date) {
          const fmt = d => d ? new Date(d).toLocaleDateString('th-TH', {
            day: 'numeric',
            month: 'short',
            year: '2-digit'
          }) : '?';
          lines.push(`   📅 ${fmt(s.start_date)} – ${fmt(s.end_date)}`);
        }
        return lines.join('\n');
      }).join('\n\n');
    },
    formatEntryTime(entry, field) {
      let digits = (entry[field] || '').replace(/\D/g, '');
      // clamp hours ≤ 23
      if (digits.length >= 2) {
        let h = parseInt(digits.slice(0, 2), 10);
        if (h > 23) {
          h = 23;
          digits = '23' + digits.slice(2);
        }
      }
      // clamp minutes ≤ 59
      if (digits.length >= 4) {
        let m = parseInt(digits.slice(2, 4), 10);
        if (m > 59) {
          digits = digits.slice(0, 2) + '59';
        }
      }
      if (digits.length >= 2) digits = digits.slice(0, 2) + ':' + digits.slice(2, 4);
      entry[field] = digits.slice(0, 5);
    },
    parseEntryStartTime(entry) {
      const parts = entry.startTimeText.split(':');
      if (parts.length === 2) {
        const [h, m] = parts.map(Number);
        if (h >= 0 && h < 24 && m >= 0 && m < 60) {
          const d = new Date();
          d.setHours(h, m, 0, 0);
          entry.startTime = d;
          // Auto-fill meeting start time if empty
          if (!entry.meetingStartTimeText && entry.createTeamsMeeting) {
            entry.meetingStartTimeText = entry.startTimeText;
            entry.meetingStartTime = new Date(d);
          }
        }
      }
    },
    parseEntryEndTime(entry) {
      const parts = entry.endTimeText.split(':');
      if (parts.length === 2) {
        const [h, m] = parts.map(Number);
        if (h >= 0 && h < 24 && m >= 0 && m < 60) {
          const d = new Date();
          d.setHours(h, m, 0, 0);
          entry.endTime = d;
          // Auto-fill meeting end time if empty
          if (!entry.meetingEndTimeText && entry.createTeamsMeeting) {
            entry.meetingEndTimeText = entry.endTimeText;
            entry.meetingEndTime = new Date(d);
          }
        }
      }
    },
    formatMeetingTime(entry, field) {
      let digits = (entry[field] || '').replace(/\D/g, '');
      // clamp hours ≤ 23
      if (digits.length >= 2) {
        let h = parseInt(digits.slice(0, 2), 10);
        if (h > 23) {
          h = 23;
          digits = '23' + digits.slice(2);
        }
      }
      // clamp minutes ≤ 59
      if (digits.length >= 4) {
        let m = parseInt(digits.slice(2, 4), 10);
        if (m > 59) {
          digits = digits.slice(0, 2) + '59';
        }
      }
      if (digits.length >= 2) digits = digits.slice(0, 2) + ':' + digits.slice(2, 4);
      entry[field] = digits.slice(0, 5);
    },
    parseMeetingStartTime(entry) {
      const parts = entry.meetingStartTimeText.split(':');
      if (parts.length === 2) {
        const [h, m] = parts.map(Number);
        if (h >= 0 && h < 24 && m >= 0 && m < 60) {
          const d = new Date();
          d.setHours(h, m, 0, 0);
          entry.meetingStartTime = d;
          entry.meetingStartTimeError = false;
        } else {
          entry.meetingStartTimeError = true;
        }
      } else if (entry.meetingStartTimeText) {
        entry.meetingStartTimeError = true;
      }
    },
    parseMeetingEndTime(entry) {
      const parts = entry.meetingEndTimeText.split(':');
      if (parts.length === 2) {
        const [h, m] = parts.map(Number);
        if (h >= 0 && h < 24 && m >= 0 && m < 60) {
          const d = new Date();
          d.setHours(h, m, 0, 0);
          entry.meetingEndTime = d;
          entry.meetingEndTimeError = false;
        } else {
          entry.meetingEndTimeError = true;
        }
      } else if (entry.meetingEndTimeText) {
        entry.meetingEndTimeError = true;
      }
    },
    calcEntryHours(entry) {
      if (!entry.startTime || !entry.endTime) return '0 ชั่วโมง';
      let diff = (entry.endTime - entry.startTime) / 3600000;
      if (diff < 0) diff += 24;
      const sh = entry.startTime.getHours() + entry.startTime.getMinutes() / 60;
      const eh = entry.endTime.getHours() + entry.endTime.getMinutes() / 60;
      if (sh < 13 && eh > 12) diff -= Math.min(eh, 13) - Math.max(sh, 12);
      return `${Math.max(0, diff).toFixed(1)} ชม.`;
    },
    addTaskEntry() {
      this.taskEntries.push({
        taskId: null,
        stepIds: [],
        location: 'GenT Office',
        workDescription: '',
        files: [],
        eventTitle: '',
        eventDetails: '',
        createCalendarEvent: false,
        createTeamsMeeting: false,
        meetingStartTime: null,
        meetingEndTime: null,
        meetingStartTimeText: '',
        meetingEndTimeText: '',
        meetingStartTimeError: false,
        meetingEndTimeError: false,
        startTimeText: '',
        endTimeText: '',
        attendees: [],
        selectedAttendee: null,
        filteredAttendees: []
      });
    },
    removeTaskEntry(idx) {
      this.taskEntries.splice(idx, 1);
    },
    getStepsForTask(id) {
      return this.workflowStepsMap[id] || [];
    },
    getStepByIdFromTask(sid, tid) {
      return this.getStepsForTask(tid).find(s => s.id === sid);
    },
    getStepNumberFromTask(sid, tid) {
      return this.getStepsForTask(tid).findIndex(s => s.id === sid) + 1;
    },
    getStepStatusColor(step) {
      if (!step) return '#9ca3af';
      if (step.status === 'completed') return '#10b981';
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (step.end_date && today > new Date(step.end_date).setHours(0, 0, 0, 0)) return '#ef4444';
      if (step.has_work_logged) return '#f59e0b';
      return '#9ca3af';
    },
    getStepStatusLabel(step) {
      if (!step) return 'รอดำเนินการ';
      if (step.status === 'completed') return 'เสร็จสิ้น';
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (step.end_date && today > new Date(step.end_date).setHours(0, 0, 0, 0)) return 'เกินกำหนด';
      if (step.has_work_logged) return 'กำลังดำเนินการ';
      return 'รอดำเนินการ';
    },
    isStepCompleted(step) {
      return step?.status === 'completed';
    },
    getTaskSO(id) {
      return this.tasks.find(t => t.id === id)?.so_number;
    },
    getTaskName(id) {
      return this.tasks.find(t => t.id === id)?.task_name;
    },
    handleFileUploadEntry(event, entry) {
      entry.files = [...(entry.files || []), ...Array.from(event.target.files)];
    },
    async loadUsers() {
      try {
        const response = await this.$http.get('/api/users');
        this.users = response.data.map(user => ({
          ...user,
          name: `${user.firstname} ${user.lastname}${user.nickname ? ` (${user.nickname})` : ''}`.trim(),
          email: user.email
        }));
        this.users.unshift({
          name: 'Engineers Group',
          email: 'engineers@gent-s.com',
          position: 'Group Email',
          department: 'Engineer'
        });
      } catch (err) {
        console.error('Load users error:', err);
      }
    },
    searchAttendees(event, entry) {
      const query = event.query.toLowerCase().trim();
      if (query) {
        const matched = this.users.filter(user => user.name.toLowerCase().includes(query) || user.email.toLowerCase().includes(query) || user.position && user.position.toLowerCase().includes(query) || user.department && user.department.toLowerCase().includes(query));
        const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(query);
        const alreadyInList = matched.some(u => u.email.toLowerCase() === query);
        if (isEmail && !alreadyInList) {
          matched.push({
            name: query,
            email: query,
            position: 'ภายนอก',
            department: ''
          });
        }
        // ถ้าไม่มี match เลย → ส่ง null เพื่อไม่ให้ panel เปิด
        entry.filteredAttendees = matched.length > 0 ? matched : null;
      } else {
        entry.filteredAttendees = this.users.slice();
      }
    },
    showAllAttendees(entry) {
      entry.filteredAttendees = this.users.slice();
    },
    onAttendeeEnter(entry) {
      const val = entry.selectedAttendee;
      // ถ้าเลือกจาก suggestion แล้ว (เป็น object)
      if (val && typeof val === 'object' && val.email) {
        this.onAttendeeSelect({
          value: val
        }, entry);
        return;
      }
      // ถ้าพิมพ์ email ภายนอก
      const text = (typeof val === 'string' ? val : '').trim();
      const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text);
      if (isEmail) {
        const exists = entry.attendees.some(a => a.email.toLowerCase() === text.toLowerCase());
        if (!exists) {
          entry.attendees.push({
            email: text,
            name: text,
            position: 'ภายนอก',
            department: ''
          });
        }
        entry.selectedAttendee = null;
      }
    },
    onAttendeeSelect(event, entry) {
      const attendee = event.value;
      if (attendee && attendee.email) {
        const exists = entry.attendees.some(a => a.email === attendee.email);
        if (!exists) {
          entry.attendees.push({
            email: attendee.email,
            name: attendee.name,
            position: attendee.position || '',
            department: attendee.department || ''
          });
        }
      }
      this.$nextTick(() => {
        entry.selectedAttendee = null;
      });
    },
    loadStatusOptions() {
      const saved = localStorage.getItem('work_statuses');
      this.statusOptions = saved ? JSON.parse(saved) : [];
    },
    async uploadFilesForEntry(entry) {
      if (!entry.files || entry.files.length === 0) return [];
      try {
        const formData = new FormData();
        entry.files.forEach(file => formData.append('files', file));
        const response = await this.$http.post('/api/files/upload?type=daily_work', formData, {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        });
        return response.data.files || [];
      } catch (error) {
        console.error('File upload error:', error);
        this.$toast.add({
          severity: 'error',
          summary: 'อัปโหลดไฟล์ไม่สำเร็จ',
          detail: error.response?.data?.error || error.message,
          life: 5000
        });
        return [];
      }
    },
    async submitForm() {
      if (this.isSubmitting) return;
      this.isSubmitting = true;

      // Validate date
      if (this.formData.useDateRange) {
        if (!this.formData.startDate || !this.formData.endDate) {
          this.$toast.add({
            severity: 'warn',
            summary: 'กรุณาเลือกวันที่เริ่มต้นและสิ้นสุด',
            life: 3000
          });
          this.isSubmitting = false;
          return;
        }
        if (this.formData.endDate < this.formData.startDate) {
          this.$toast.add({
            severity: 'warn',
            summary: 'วันสิ้นสุดต้องมากกว่าหรือเท่ากับวันเริ่มต้น',
            life: 3000
          });
          this.isSubmitting = false;
          return;
        }
      } else {
        if (!this.formData.workDate) {
          this.$toast.add({
            severity: 'warn',
            summary: 'กรุณาเลือกวันที่',
            life: 3000
          });
          this.isSubmitting = false;
          return;
        }
      }
      const validEntries = this.taskEntries.filter(e => e.taskId);
      if (validEntries.length === 0) {
        this.$toast.add({
          severity: 'error',
          summary: 'ข้อผิดพลาด',
          detail: 'กรุณาเลือกโครงการอย่างน้อย 1 รายการ',
          life: 3000
        });
        return;
      }

      // Validate time and required fields
      for (const e of validEntries) {
        if (!e.startTime || !e.endTime) {
          this.$toast.add({
            severity: 'error',
            summary: 'ข้อผิดพลาด',
            detail: 'กรุณากรอกเวลาเริ่มและสิ้นสุดให้ครบทุกโครงการ',
            life: 3000
          });
          return;
        }
        if (!e.location || !e.workDescription) {
          this.$toast.add({
            severity: 'warn',
            summary: 'กรุณากรอกข้อมูลให้ครบ',
            detail: 'สถานที่และรายละเอียดงานเป็นข้อมูลที่จำเป็น',
            life: 3000
          });
          return;
        }
      }
      try {
        const userId = localStorage.getItem('soc_user_id');
        const submittedAt = new Date().toISOString();

        // Generate date array
        const datesToSubmit = [];
        if (this.formData.useDateRange) {
          const start = new Date(this.formData.startDate);
          const end = new Date(this.formData.endDate);
          start.setHours(0, 0, 0, 0);
          end.setHours(0, 0, 0, 0);
          for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
            datesToSubmit.push(new Date(d));
          }
        } else {
          datesToSubmit.push(new Date(this.formData.workDate));
        }

        // Submit for each date and each entry
        const totalSubmissions = datesToSubmit.length * validEntries.length;
        let completedSubmissions = 0;
        await Promise.all(datesToSubmit.map(async workDate => {
          return Promise.all(validEntries.map(async entry => {
            const uploadedFiles = await this.uploadFilesForEntry(entry);
            const eventDetails = entry.eventDetails || '';

            // Calculate total hours
            let totalHours = 0;
            if (entry.startTime && entry.endTime) {
              const start = new Date(entry.startTime);
              let end = new Date(entry.endTime);
              if (end <= start) end.setDate(end.getDate() + 1);
              let diff = (end - start) / 3600000;
              const sh = start.getHours() + start.getMinutes() / 60;
              const eh = end.getHours() + end.getMinutes() / 60;
              if (sh < 13 && eh > 12) diff -= Math.min(eh, 13) - Math.max(sh, 12);
              totalHours = Math.max(0, diff);
            }
            const result = await this.$http.post('/api/daily-work', {
              task_id: entry.taskId,
              step_ids: entry.stepIds.length > 0 ? entry.stepIds : [],
              work_date: this.formatDate(workDate),
              start_time: this.formatTime(entry.startTime),
              end_time: this.formatTime(entry.endTime),
              total_hours: totalHours,
              location: entry.location,
              work_description: entry.workDescription,
              files: uploadedFiles,
              user_id: userId,
              submitted_at: submittedAt,
              create_calendar_event: entry.createCalendarEvent && !!entry.eventTitle,
              event_title: entry.eventTitle || '',
              event_details: eventDetails,
              create_teams_meeting: entry.createTeamsMeeting || false,
              meeting_start_time: this.formatTime(entry.createTeamsMeeting ? entry.meetingStartTime || entry.startTime : entry.startTime),
              meeting_end_time: this.formatTime(entry.createTeamsMeeting ? entry.meetingEndTime || entry.endTime : entry.endTime),
              attendees: entry.attendees || []
            });
            completedSubmissions++;
            return result;
          }));
        }));
        const dateText = this.formData.useDateRange ? `${datesToSubmit.length} วัน` : '1 วัน';
        this.$toast.add({
          severity: 'success',
          summary: 'สำเร็จ',
          detail: `บันทึกงานรายวัน ${validEntries.length} โครงการ × ${dateText} = ${totalSubmissions} รายการเรียบร้อยแล้ว`,
          life: 5000
        });
        window.dispatchEvent(new CustomEvent('taskUpdated'));
        window.dispatchEvent(new CustomEvent('taskStatusChanged'));
        this.$emit('submit-work');
      } catch (err) {
        console.error('Submit error:', err);
        this.$toast.add({
          severity: 'error',
          summary: 'เกิดข้อผิดพลาด',
          detail: err.response?.data?.error || err.userMessage || 'ไม่สามารถบันทึกข้อมูลได้ กรุณาลองใหม่อีกครั้ง',
          life: 5000
        });
      } finally {
        this.isSubmitting = false;
      }
    },
    formatDate(date) {
      if (!date) return null;
      const d = new Date(date);
      return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    },
    formatTime(date) {
      if (!date) return null;
      if (typeof date === 'string' && /^\d{2}:\d{2}/.test(date)) return date.slice(0, 5);
      const d = new Date(date);
      return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
    },
    resetForm() {
      if (!confirm('ล้างข้อมูลทั้งหมด?')) return;
      location.reload();
    }
  }
};
